    add(issues,("R2-" if R2_MODE else "")+"ISS-GLOBAL-ADMIN","","LIMITATION","current admin SEO fields/current admin alt","Not supplied","Storefront metadata and product.js media alt were readable, but no Shopify admin export was provided.","Storefront values cannot prove admin fields or future import mapping.","Provide a frozen Shopify admin/export snapshot before deployment approval.",str(SOURCE),"Admin export revision and hash are frozen and compared.")
    add(issues,("R2-" if R2_MODE else "")+"ISS-GLOBAL-SNAPSHOT-HTML","","LIMITATION","phase-1 HTML snapshot","Phase-1 HTML fetch returned HTTP 403.","Frozen product JSON/body/options/gallery URLs match live, but old rendered metadata cannot be compared directly.","An unavailable old HTML snapshot is not evidence of drift.","Capture a fresh immutable HTML snapshot for the next revision.",str(QA_DIR/"live_source_comparison.json"),"Both old and new readable HTML snapshots are available with hashes.")

    issue_by={}
    for x in issues: issue_by.setdefault(x["product_key"],[]).append(x)
    reasons=dict(common.REASONS); reasons["P2"]="Đối chiếu specification, variants, components và personalization với product.js live và ảnh gốc."; reasons["K2"]="Đã đọc primary và comparator SERP theo US commercial intent; không dùng claim volume."; reasons["E1"]="Kiểm tra chuỗi evidence và giới hạn do thiếu Shopify admin export."
    criteria=[]; qproducts=[]
    for ix,p in enumerate(products):
        pos=51+ix; pk=p["product_key"]; ims=[x for x in qa_images if x["product_key"]==pk]; image_avg=sum(x["image_final_score"] for x in ims)/len(ims); refs=[x["issue_id"] for x in issue_by.get(pk,[])]
        for cid,weight in PW.items():
            if cid=="I1": assessment,rating,earned="DERIVED",image_avg/100,weight*image_avg/100; reason=f"Tính từ trung bình {len(ims)} ảnh: {image_avg:.4f}/100."
            else: assessment=ASSESS[pos][cid]; rating=R[assessment]; earned=weight*rating; reason=reasons[cid]
            criteria.append({"product_key":pk,"criterion_id":cid,"weight":weight,"assessment":assessment,"rating":rating,"earned_points":earned,"assessed_weight":weight,"reason":reason,"evidence_refs":[p["evidence_id"],p["product_url"],f"serp_qa_{pos:03d}"],"issue_refs":refs})
        score=sum(x["earned_points"] for x in criteria if x["product_key"]==pk); sev=Counter(x["severity"] for x in issue_by.get(pk,[])); status="QA_FAIL" if sev["CRITICAL"] or score<70 else ("QA_REVISE" if score<85 or sev["MAJOR"] else "QA_PASS")
        qproducts.append({"inventory_position":pos,"product_key":pk,"url":p["product_url"],"handle":p["Handle"],"product_id":str(p["product_id"]),"revision":"r2" if R2_MODE else "r1","verified_points":score,"assessed_weight":100,"score_lower_bound":score,"score_upper_bound":score,"final_score":score,"qa_status":status,"keyword_evidence_level":p["keyword_evidence_level"],"images_expected":len(ims),"images_checked":len(ims),"image_inventory_complete":True,"image_coverage":1.0,"critical_count":sev["CRITICAL"],"major_count":sev["MAJOR"],"minor_count":sev["MINOR"],"limitation_count":sev["LIMITATION"],"issue_refs":refs,"evidence_refs":[p["evidence_id"],p["product_url"],f"serp_qa_{pos:03d}"]})

    avg=sum(x["final_score"] for x in qproducts)/10; statuses=Counter(x["qa_status"] for x in qproducts); sevs=Counter(x["severity"] for x in issues); source_hash=common.sha256(SOURCE)
    summary=[{"metric":"rubric_version","value":"prompt_qa.md@sha256:"+common.sha256(ROOT/"seo-prompt/jeminise/prompt_qa.md"),"definition":"Rubric QA áp dụng."},{"metric":"source_workbook","value":str(SOURCE),"definition":"Workbook giai đoạn 1 đóng băng; không chỉnh sửa."},{"metric":"source_sha256_at_handoff","value":source_hash,"definition":"Hash tính lại khi hoàn tất."},{"metric":"qa_run_id","value":QA_RUN_ID,"definition":"Run QA độc lập."},{"metric":"batch_id","value":BATCH,"definition":"Inventory positions 51-60."},{"metric":"products_checked","value":10,"definition":"Đúng 10 product key."},{"metric":"images_checked","value":78,"definition":"78/78 ảnh mở trực tiếp ở độ phân giải gốc."},{"metric":"batch_final_score","value":avg,"definition":"Trung bình 10 final_score; không bù lỗi chặn."},{"metric":"batch_result","value":"NOT_PASSED","definition":"Lô chỉ đạt khi mọi sản phẩm QA_PASS."},{"metric":"status_counts","value":dict(statuses),"definition":"Số sản phẩm theo kết luận."},{"metric":"issue_counts","value":dict(sevs),"definition":"Số phát hiện theo severity."},{"metric":"admin_limitation","value":"No Shopify admin export","definition":"Không suy ra admin fields hoặc dynamic personalization app."},{"metric":"xlsx_status","value":"COMPLETE","definition":"XLSX tạo bằng openpyxl, kiểm tra cấu trúc/công thức và render."}]
    serp=[]
